/*!50003 DROP PROCEDURE IF EXISTS `sp_compute_payroll` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_compute_payroll`(
    IN p_emp_id INT,
    IN p_start_date DATE,
    IN p_end_date DATE,
    OUT p_total_hours DOUBLE,
    OUT p_ot_hours DOUBLE,
    OUT p_net_pay DOUBLE
)
BEGIN
    DECLARE v_hourly_rate DOUBLE;
    DECLARE v_daily_wage DOUBLE;

    
    SELECT daily_wage INTO v_daily_wage
    FROM employee_applicants
    WHERE id = p_emp_id;

    
    SET v_hourly_rate = v_daily_wage / 8.0;

    
    SELECT 
        COALESCE(SUM(LEAST(TIMESTAMPDIFF(MINUTE, time_in, time_out) / 60.0, 8.0)), 0),
        COALESCE(SUM(GREATEST((TIMESTAMPDIFF(MINUTE, time_in, time_out) / 60.0) - 8.0, 0)), 0)
    INTO p_total_hours, p_ot_hours
    FROM attendance_logs
    WHERE employee_id = p_emp_id 
      AND log_date BETWEEN p_start_date AND p_end_date
      AND time_in IS NOT NULL AND time_out IS NOT NULL;

    
    SELECT 
        COALESCE(SUM(
            
            (LEAST(TIMESTAMPDIFF(MINUTE, a.time_in, a.time_out) / 60.0, 8.0) * v_hourly_rate * CASE 
                WHEN h.type = 'REGULAR' THEN 2.0                 
                WHEN h.type = 'SPECIAL_NON_WORKING' THEN 1.3     
                ELSE 1.0                                         
            END)
            +
            
            (GREATEST((TIMESTAMPDIFF(MINUTE, a.time_in, a.time_out) / 60.0) - 8.0, 0) * v_hourly_rate * 1.25 *
            CASE 
                WHEN h.type = 'REGULAR' THEN 2.0                 
                WHEN h.type = 'SPECIAL_NON_WORKING' THEN 1.3     
                ELSE 1.0                                         
            END)
        ), 0)
    INTO p_net_pay
    FROM attendance_logs a
    LEFT JOIN holidays h ON a.log_date = h.date
    WHERE a.employee_id = p_emp_id 
      AND a.log_date BETWEEN p_start_date AND p_end_date
      AND a.time_in IS NOT NULL AND a.time_out IS NOT NULL;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
